/* Login mobile aprovado: Zafira central, Spins laterais e menos piso vazio. */
@media (max-width:600px){
#auth-root .auth-shell.auth-shell::before,
#auth-root .auth-shell.auth-shell::after{background-image:url("data:image/png;base64,");}
#auth-root .auth-shell.auth-shell::after{width:min(100vw,calc(100dvh * .666667));height:min(100dvh,calc(100vw * 1.5));background-size:100% 100%;background-position:center;}
#auth-root .auth-card.auth-card{width:min(100%,310px);padding:17px 18px;}
#auth-root .auth-card .auth-mark{width:30px;height:30px;font-size:19px;margin-bottom:8px;}
#auth-root .auth-card h1{font-size:20px;}
#auth-root .auth-card .auth-fields{margin-top:13px;gap:10px;}
#auth-root .auth-card .auth-submit{margin-top:13px;}
#auth-root .auth-card .auth-foot{margin-top:11px;}
#auth-root .auth-card .auth-private{margin-top:12px;padding-top:11px;}
}
